Translate("ptBR", "mor-rogal", {
	title = "Mor'rogal",
	subtitle = "Vidente da Rocha do Sol",
	found = "As colinas acima do Retiro Rocha do Sol",
	hint = [=[Suba as colinas acima da Rocha do Sol e fale com o tauren que sente a tensão no ar.]=],
	allegiance = "Horda · Penhasco do Trovão",
	sections = {
		{
			title = "Resumo",
			text = [=[Mor'rogal é um xamã {link:tauren}tauren{/link} que se mantém nas colinas acima do {link:sun-rock-retreat}Retiro Rocha do Sol{/link}. Ele sente quando algo está errado na terra. Ultimamente tem sentido isso com força. O problema que ele percebeu não eram os goblins nem as harpias, mas algo no fundo das montanhas, onde os kobolds da {link:boulderslide-ravine}Ravina da Avalanche{/link} vinham escavando.]=],
		},
		{
			title = "Importância",
			text = [=[Mor'rogal descobriu uma das ameaças mais graves das {link:stonetalon-mountains}Torres de Pedra{/link}: um terrano adormecido, uma criatura dos titãs, enterrado em ressonita sob a ravina. Se ele tivesse despertado com toda a força, acreditava Mor'rogal, todas as Torres de Pedra estariam perdidas.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele envia exploradores à caverna da {link:boulderslide-ravine}Ravina da Avalanche{/link} para descobrir o que os kobolds estão extraindo.
• Ele reconhece a magia terrana na ressonita graças a uma velha lenda.
• Ele encanta a ressonita para romper o barril que guardava o terrano {link:goggeroc}Goggeroc{/link}.
• Ele encontra um uso para as pedras-do-sol douradas que as harpias acumulam.]=],
		},
	},
	chapters = {
		{
			title = "O Cristal nas Profundezas",
			hint = "Descubra o que os kobolds procuram na Ravina da Avalanche.",
			text = [=[As amostras de minério voltaram da caverna, e Mor'rogal as revirou nas mãos até se lembrar. A ressonita traz um vestígio de magia terrana. As lendas dizem que os terranos foram feitos pelos titãs para moldar a própria terra. Se os kobolds tinham cavado fundo o bastante para encontrar ressonita, tinham cavado fundo o bastante para encontrar um terrano.]=],
		},
		{
			title = "O Despertar do Terrano",
			hint = [=[Desperte o adormecido sob a ravina antes que ele desperte por conta própria.]=],
			text = [=[Mor'rogal não podia impedir que {link:goggeroc}Goggeroc{/link} despertasse. Escolheu despertá-lo primeiro, enquanto ele estava fraco do longo sono. Com um cristal encantado o barril foi rompido, e o terrano foi morto antes que sua força voltasse. Mor'rogal chamou isso de um feito que toda {link:kalimdor}Kalimdor{/link} ficaria devendo.]=],
		},
	},
	mentions = {
		{ text = "{link:boulderslide-ravine}Ravina da Avalanche{/link}" },
		{ text = "O Despertar do Terrano" },
		{
			text = [=[Bugigangas Furissangue, enviadas por {link:maggran-earthbinder}Maggran{/link}]=],
		},
	},
	bonds = {
		{ id = "goggeroc", name = "Goggeroc", note = "o adormecido que ele temia" },
		{ id = "maggran-earthbinder", name = "Maggran Earthbinder", note = "manda-lhe pedras-do-sol" },
	},
})

Translate("ptBR", "braelyn-firehand", {
	title = "Braelyn Firehand",
	subtitle = "Serva de um Senhor Oculto",
	found = "Retiro Rocha do Sol",
	hint = [=[Procure a forasteira da Rocha do Sol que odeia os druidas do morro.]=],
	allegiance = "Desconhecida · Um senhor em Jaedenar",
	aliases = { "Braelyn" },
	sections = {
		{
			title = "Resumo",
			text = [=[Braelyn Firehand vive entre a {link:horde}Horda{/link} no {link:sun-rock-retreat}Retiro Rocha do Sol{/link}, mas não é amiga da fé dos taurens. Odeia os druidas do {link:stonetalon-peak}Morro das Torres de Pedra{/link}, que, em suas palavras, sufocam o fluxo da magia pelas montanhas. Foi enviada por um senhor que espera em {link:jaedenar}Jaedenar{/link}, muito ao norte, e não pode voltar até que seu trabalho esteja feito. Fala da era de {link:azshara}Azshara{/link} como se se lembrasse dela.]=],
		},
		{
			title = "Importância",
			text = [=[Braelyn é um fio de algo antigo e sombrio nas {link:stonetalon-mountains}Torres de Pedra{/link}. Chama o templo arruinado do morro de "nosso" templo de {link:azshara}Azshara{/link}. Conheceu {link:keeper-ordanus}Ordanus{/link}, um filho de {link:cenarius}Cenarius{/link}, há muito tempo, e diz que ele se julgava acima até dos Bem-nascidos. Seja o que for, ela tem fome de magia como outros têm fome de pão.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ela busca a morte dos druidas cenarianos e dos filhos de {link:cenarius}Cenarius{/link} no morro.
• Ela caça {link:keeper-ordanus}Ordanus{/link}, que os druidas levaram em segredo para o {link:ashenvale}Vale Gris{/link}.
• Ela arranca os segredos do {link:the-talon-den}Retiro do Gadanho{/link} de um druida capturado.]=],
		},
		{
			title = "Não Registrado",
			text = [=[O nome de seu senhor não está escrito. Tampouco está escrito por que a {link:horde}Horda{/link} a deixa viver na {link:sun-rock-retreat}Rocha do Sol{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Um Poço Cheio de Furos",
			hint = [=[Ajude a feiticeira a afrouxar o domínio dos druidas sobre as montanhas.]=],
			text = [=[Nas {link:stonetalon-mountains}Torres de Pedra{/link}, diz Braelyn, recorrer à magia é como tirar água com um balde cheio de furos. Quando os druidas e os filhos de {link:cenarius}Cenarius{/link} caíram, ela sentiu o fluxo voltar, doce e impetuoso. Os {link:night-elves}kaldorei{/link}, diz ela, são tolos por desprezá-lo.]=],
		},
		{
			title = "A Cabeça de Ordanus",
			hint = "Encontre o filho de Cenarius que os druidas esconderam dela.",
			text = [=[Com sua visão, Braelyn o encontrou: {link:keeper-ordanus}Ordanus{/link}, um dos filhos mais velhos do deus da floresta, escondido no alto de uma grande árvore no {link:raynewood-retreat}Bosque Real{/link}, no {link:ashenvale}Vale Gris{/link}. Os druidas o haviam tirado do morro antes que ela pudesse alcançá-lo. Quando a cabeça dele lhe foi trazida, ela a olhou sem piedade. Sua cabeça, disse ela, já não se erguia tão alto.]=],
		},
		{
			title = "O Tesouro do Retiro",
			hint = "Siga o segredo que Braelyn arrancou de um druida.",
			text = [=[Os druidas do {link:the-talon-den}Retiro do Gadanho{/link} haviam construído um cuidadoso enigma de chaves para guardar seus tesouros. Braelyn arrancou o segredo de um deles: uma chave escondida numa lanterna, três esconderijos e um tesouro no coração do retiro.]=],
		},
	},
	mentions = {
		{ text = "O Legado de {link:cenarius}Cenarius{/link}" },
		{ text = "{link:keeper-ordanus}Ordanus{/link}" },
		{ text = "O Retiro" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Guardião Albagorm", note = "guarda o morro que ela despreza" },
	},
})

Translate("ptBR", "witch-doctor-jin-zil", {
	title = "Mandingueiro Jin'Zil",
	subtitle = "Mandingueiro de Malaka'jin",
	found = "Sua cabana em Malaka'jin",
	hint = [=[Encontre o mandingueiro de Malaka'jin que mantém três jaulas ao lado de sua cabana.]=],
	allegiance = "Horda · Trolls Lançanegra",
	aliases = { "Jin'Zil" },
	sections = {
		{
			title = "Resumo",
			text = [=[Jin'Zil é um mandingueiro troll de {link:malaka-jin}Malaka'jin{/link}. É alegre, cruel e velho nos caminhos de seu ofício. Ao lado de sua cabana há três jaulas, e em cada jaula há um {link:night-elves}elfo noturno{/link}. Ele os chama de seus amiguinhos, e pretende preparar para eles uma prova do que eles chamam de magia da floresta.]=],
		},
		{
			title = "Importância",
			text = [=[Jin'Zil lembra que a guerra entre a {link:horde}Horda{/link} e os {link:night-elves}kaldorei{/link} não é travada só no {link:ashenvale}Vale Gris{/link}. Ele também é um elo com dias mais antigos. Lembra-se da vez em que seu amigo Rokhan partiu com um mok'nathal selvagem para matar a irmã mais velha da {link:harpies}harpia{/link} Serena Bloodfeather.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele mantém três elfos noturnos prisioneiros em jaulas em {link:malaka-jin}Malaka'jin{/link}.
• Ele prepara para seus cativos uma poção de seiva, bigodes, olhos e escama de dragão feérico.
• Ele fica sabendo por seu velho amigo Darsok que a última das Bloodfeather está morta.]=],
		},
	},
	chapters = {
		{
			title = "Magia da Floresta",
			hint = "Reúna os estranhos ingredientes do mandingueiro.",
			text = [=[Para sua poção, Jin'Zil queria seiva das {link:stonetalon-mountains}Torres de Pedra{/link}, bigodes de corredores-do-crepúsculo, os olhos dos corcéis e a escama de um dragão feérico. Muitos olhos, insistia; nunca são suficientes. O que a poção fazia aos elfos nas jaulas, ele não disse. Só prometeu que os faria se sentir em casa.]=],
		},
		{
			title = "Uma Carta dos Sertões",
			hint = "Leve a carta de um velho amigo a Malaka'jin.",
			text = [=[Jin'Zil não tinha notícias de Darsok havia muitos anos. A carta lhe contou que Serena Bloodfeather estava morta, a última de sua linhagem. Trouxe de volta sua juventude, quando viu Rokhan partir com um caçador mok'nathal para matar a irmã mais velha dela.]=],
		},
	},
	mentions = {
		{ text = "Carta para Jin'Zil" },
		{ text = "A Magia da Floresta de Jin'Zil" },
	},
	bonds = {
		{ id = "ken-zigla", name = "Ken'zigla", note = "prepara poções em Malaka'jin" },
		{ id = "xen-zilla", name = "Xen'Zilla", note = "da mesma aldeia" },
	},
})

Translate("ptBR", "ziz-fizziks", {
	title = "Ziz Fizziks",
	subtitle = "Engenheiro que Mudou de Lado",
	found = "Um acampamento na borda oeste do Rochedo Cortavento",
	hint = [=[Encontre o engenheiro goblin que acampa na borda oeste do Rochedo Cortavento.]=],
	allegiance = "Sindicato dos Engenhoqueiros · Cartel Bondebico",
	aliases = { "Ziz" },
	sections = {
		{
			title = "Resumo",
			text = [=[Ziz Fizziks já foi o engenheiro-chefe das obras da {link:venture-company}Empreendimentos S.A.{/link} nas {link:stonetalon-mountains}Torres de Pedra{/link}. Então a companhia contratou um {link:gnomes}gnomo{/link}, {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}, e o pôs no comando. Ziz foi dispensado. Ficou tão ofendido que implorou a Sputtervalve, de {link:ratchet}Vila Catraca{/link}, que lhe arranjasse trabalho com o Sindicato dos Engenhoqueiros, e agora espiona seus antigos patrões de um acampamento na borda do rochedo.]=],
		},
		{
			title = "Importância",
			text = [=[Ziz mostra que a lealdade goblin vai exatamente tão fundo quanto o pagamento goblin. Ele odeia o que a companhia fez com as montanhas, ou pelo menos é o que diz. Odeia muito mais ter sido preterido por um {link:gnomes}gnomo{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele deixou um agente, {link:piznik}Piznik{/link}, dentro da mina da companhia para colher segredos.
• Ele rouba os planos do Super Reaper 6000, a grande máquina de cortar madeira da companhia.
• Ele manda os documentos e manuais da companhia a Sputtervalve, em {link:ratchet}Vila Catraca{/link}.
• Ele põe preço na cabeça de {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}.]=],
		},
	},
	chapters = {
		{
			title = "O Super Reaper",
			hint = [=[Ajude o engenheiro a roubar os planos da grande máquina da companhia.]=],
			text = [=[A {link:venture-company}Empreendimentos S.A.{/link} havia construído uma máquina enorme para cortar madeira, e Sputtervalve queria seus planos. Ziz não podia ir buscá-los ele mesmo, pois {link:gerenzo-wrenchwhistle}Gerenzo{/link} o queria morto assim que o visse. Quando os planos chegaram às suas mãos, ele mal conseguiu lê-los. Perguntou-se em voz alta como os gnomos tinham conseguido inventar a roda.]=],
		},
		{
			title = "O Braço Mecânico",
			hint = "Derrube o gnomo que tomou o lugar de Ziz.",
			text = [=[Ziz vira {link:gerenzo-wrenchwhistle}Gerenzo{/link} uma vez, e não esquecera a carne apodrecida nem as engrenagens. Jamais conseguiria abrir caminho à força até a torre do {link:gnomes}gnomo{/link}. Quando o braço mecânico de Gerenzo foi posto diante dele, Ziz balançou a cabeça. Por que cortar um braço para substituí-lo, perguntou, quando se podia simplesmente acrescentar um terceiro?]=],
		},
	},
	mentions = {
		{ text = "Ziz Fizziks, enviado por Sputtervalve" },
		{ text = "Super Reaper 6000" },
		{ text = "Mais Instruções" },
		{ text = "As Ordens de {link:gerenzo-wrenchwhistle}Gerenzo{/link}" },
		{
			text = [=[Mais Instruções, de volta de {link:ratchet}Vila Catraca{/link}]=],
		},
		{ text = "{link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}" },
	},
	bonds = {
		{ id = "piznik", name = "Piznik", note = "seu agente na mina" },
		{ id = "gerenzo-wrenchwhistle", name = "Gerenzo Wrenchwhistle", note = "tomou o seu lugar" },
		{ id = "gazlowe", name = "Gazlowe", note = "governa o porto onde trabalha o seu novo senhor" },
	},
})

Translate("ptBR", "gerenzo-wrenchwhistle", {
	title = "Gerenzo Wrenchwhistle",
	subtitle = "Supervisor da Empreendimentos S.A. nas Torres de Pedra",
	found = "Bem acima do Lago do Rochedo, perto da grande roda-d'água",
	hint = [=[Enfrente o gnomo que vigia as obras dos goblins bem acima do Lago do Rochedo.]=],
	allegiance = "Empreendimentos S.A.",
	aliases = { "Gerenzo" },
	sections = {
