		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica diz de onde Gerenzo veio, como perdeu seus membros, nem por que um {link:gnomes}gnomo{/link} serviria à {link:venture-company}Empreendimentos S.A.{/link}]=],
		},
	},
	chapters = {
		{
			title = "O Minério Verde-dourado",
			hint = "Descubra o que o gnomo está escavando.",
			text = [=[Ninguém abaixo de Gerenzo sabia por que ele queria tanto do minério verde-dourado. {link:piznik}Piznik{/link} contrabandeou uma amostra para fora da mina, e {link:ziz-fizziks}Ziz{/link} enviou um pedaço aos engenheiros de Undermine, guardando um pouco para si. O que é o minério, e o que Gerenzo pretende fazer com ele, não está escrito.]=],
		},
	},
	mentions = {
		{ text = "As Ordens de Gerenzo" },
		{ text = "Gerenzo Wrenchwhistle" },
	},
	bonds = {
		{ id = "ziz-fizziks", name = "Ziz Fizziks", note = "o engenheiro que ele substituiu" },
		{ id = "piznik", name = "Piznik", note = "mandado para as minas" },
		{ id = "gaxim-rustfizzle", name = "Gaxim Rustfizzle", note = "um gnomo do outro lado" },
	},
})

